import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.DnrXFDHb.js";const g=JSON.parse('{"title":"工作流和模板区别","description":"区分 Prompt、模板、Workflow 与 Agent，理解固定流程的输入输出、复用方式、可靠性和适用场景。","frontmatter":{"description":"区分 Prompt、模板、Workflow 与 Agent，理解固定流程的输入输出、复用方式、可靠性和适用场景。"},"headers":[],"relativePath":"workflows/workflow-vs-template.md","filePath":"workflows/workflow-vs-template.md","lastUpdated":1788335970000}'),n={name:"workflows/workflow-vs-template.md"};function s(i,t,o,d,p,h){return e(),l("div",null,[...t[0]||(t[0]=[r(`<h1 id="工作流和模板区别" tabindex="-1">工作流和模板区别 <a class="header-anchor" href="#工作流和模板区别" aria-label="Permalink to &quot;工作流和模板区别&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 模板是“固定骨架加填空”，解决从哪开始复用；工作流是“多步骤的执行编排”，带顺序、条件分支和工具调用，解决每一步怎么走。格式固定、人工判断为主的任务用模板就够了，步骤有依赖、需要分支或工具时才值得升级为工作流。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/prompting/basics">Prompt 入门</a>，知道怎么把单个任务写成清晰的任务说明。</li><li>不要求用过任何自动化或绘画工具；本页的例子只用文字推演。</li><li>先接受一个边界：本页讲“什么时候用哪种、各自怎么失效”，不提供具体工具的搭建教程。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>说出模板和工作流分别是什么，以及两者可以怎样组合。</li><li>判断一个任务该用模板，还是该拆成工作流。</li><li>列出“该升级为工作流”的判断标准。</li><li>说明工作流的代价：维护、调试和新的失败模式。</li><li>在 AI 绘画工具里认出这两个概念的对应物。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="模板是什么-固定骨架加填空" tabindex="-1">模板是什么：固定骨架加填空 <a class="header-anchor" href="#模板是什么-固定骨架加填空" aria-label="Permalink to &quot;模板是什么：固定骨架加填空&quot;">​</a></h3><p>模板是一份可复用的固定骨架，留出空位，每次按需填入变化的内容。骨架不变，变的只是填空：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>周报模板：</span></span>
<span class="line"><span>【本周进展】</span></span>
<span class="line"><span>- （填入……）</span></span>
<span class="line"><span>【下周计划】</span></span>
<span class="line"><span>- （填入……）</span></span>
<span class="line"><span>【需要的支持】</span></span>
<span class="line"><span>- （填入……）</span></span></code></pre></div><p>模板解决的是“从哪开始”：格式稳定、不必每次从头构思，填空者仍然掌握全部判断。它的适用前提是任务结构稳定——每周都是这几栏，只是内容不同。</p><p>模板的失效场景：任务结构本身在变（这周做复盘、下周做调研，同一副骨架套不上）；内容需要大量判断和取舍（骨架给不了判断）；填空项之间有依赖（后面填什么取决于前面发现了什么）。</p><p>模板和工作流并不互斥：一份搭好的工作流可以保存成模板，一个模板里也可以嵌着一小段固定流程。区别在重心——模板重“复用起点”，工作流重“执行逻辑”本身。</p><h3 id="工作流是什么-多步骤加条件与工具" tabindex="-1">工作流是什么：多步骤加条件与工具 <a class="header-anchor" href="#工作流是什么-多步骤加条件与工具" aria-label="Permalink to &quot;工作流是什么：多步骤加条件与工具&quot;">​</a></h3><p>工作流是一套执行编排：规定步骤顺序、每步的输入输出、遇到不同情况走哪条分支、哪些步骤交给工具或模型完成。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>步骤 1：收集资料</span></span>
<span class="line"><span>  → 步骤 2：按规则分类</span></span>
<span class="line"><span>    →（分支：结果为空则直接结束）</span></span>
<span class="line"><span>  → 步骤 3：逐类生成摘要</span></span>
<span class="line"><span>    → 步骤 4：汇总成稿</span></span>
<span class="line"><span>      → 人工确认</span></span></code></pre></div><p>把工作流和模板区分开的是三个特征：<strong>多步骤</strong>（有先后依赖）、<strong>条件分支</strong>（不同输入走不同路径）、<strong>工具调用</strong>（某一步交给检索、计算或模型）。</p><p>在 AI 绘画工具 ComfyUI 里，工作流表现为一张节点图，连线决定数据从加载模型、编码提示词到采样保存的流向。常见的绘画工作流形态：</p><ul><li>文生图：文字生成图片。</li><li>图生图：基于已有图片重新生成。</li><li>Inpaint：局部重绘。</li><li>Outpaint：向画面外扩展。</li><li>Upscale：放大和细节修复。</li><li>ControlNet / IP-Adapter（一种把参考图像风格/内容注入生成过程的适配器）：通过线稿、深度、姿势或参考图控制结构与风格。</li></ul><p>在办公自动化工具里，工作流则表现为一串带条件的动作。形态不同，结构逻辑相同。</p><h3 id="什么时候该从模板升级为工作流" tabindex="-1">什么时候该从模板升级为工作流 <a class="header-anchor" href="#什么时候该从模板升级为工作流" aria-label="Permalink to &quot;什么时候该从模板升级为工作流&quot;">​</a></h3><p>满足下列标准之一，才值得考虑升级：</p><ul><li><strong>步骤之间有依赖</strong>：上一步的输出是下一步的输入，填空表达不了顺序。</li><li><strong>需要条件分支</strong>：“如果有附件先解析附件”这类按情况走不同路径的逻辑。</li><li><strong>需要外部工具或数据</strong>：要查数据库、调模型、读文件，一个 Prompt 完成不了。</li><li><strong>量大且重复</strong>：每天或每周固定执行，人工逐步操作的成本已经明显偏高。</li></ul><p>反过来，任务简单、低频、每次内容都不同时，模板甚至一条写清楚的 Prompt 更合适——不是所有任务都值得自动化。四个标准都不满足时，别急着搭流程。</p><h3 id="工作流的代价-维护、调试与失败模式" tabindex="-1">工作流的代价：维护、调试与失败模式 <a class="header-anchor" href="#工作流的代价-维护、调试与失败模式" aria-label="Permalink to &quot;工作流的代价：维护、调试与失败模式&quot;">​</a></h3><p>工作流不是免费的升级：</p><ul><li><strong>维护成本</strong>：上游格式一变（接口、页面、文件结构），下游步骤跟着坏，流程需要长期有人管。</li><li><strong>调试更难</strong>：错误可能出在任意一步，要固定其他步骤、逐段排查。</li><li><strong>失败模式变多</strong>：某一步的错误会被后续步骤放大——假设每步正确率 95%，四步全对的概率只有约 81%（0.95 的 4 次方；RAG 多步任务中的错误连乘见<a href="/llm/rag-agent">RAG 与 Agent</a>）；还可能出现死循环重试、调用成本失控。</li></ul><p>所以工作流要在关键节点设检查点：中间结果落盘、异常时停下而不是硬着头皮继续、最终产物保留人工确认。</p><h2 id="最小推演-每周整理邮件-模板版与工作流版" tabindex="-1">最小推演：每周整理邮件，模板版与工作流版 <a class="header-anchor" href="#最小推演-每周整理邮件-模板版与工作流版" aria-label="Permalink to &quot;最小推演：每周整理邮件，模板版与工作流版&quot;">​</a></h2><p>任务：每周五把这一周的邮件整理成一页周报。</p><p>模板版：做一个周报骨架，每周人工填空——翻邮箱、挑出重要的、按骨架抄进去。整个过程是“一个模板加一个人”：判断全部由人完成，模板只管格式。邮件量不大时，这已经够用。</p><p>工作流版：把“人工逐封翻找”拆成四步：</p><table tabindex="0"><thead><tr><th>步骤</th><th>输入</th><th>处理</th><th>输出</th><th>典型失败点</th></tr></thead><tbody><tr><td>1 收集</td><td>邮箱访问权限</td><td>拉取一周邮件，过滤订阅与通知</td><td>原始邮件清单</td><td>授权过期、接口变更</td></tr><tr><td>2 分类</td><td>原始邮件清单</td><td>按项目、人事、通知分组</td><td>分组结果</td><td>边缘邮件归错组</td></tr><tr><td>3 摘要</td><td>每组邮件</td><td>逐组生成要点与待办</td><td>分组摘要</td><td>漏读附件、编造不存在的结论</td></tr><tr><td>4 汇总</td><td>分组摘要</td><td>拼装成一页周报，标注来源</td><td>待确认的草稿</td><td>拼接遗漏、未经确认就发出</td></tr></tbody></table><p>对照可以看出：模板版每一步都是“人做判断、模板管格式”；工作流版把一部分判断分给了规则和模型，人只在最后确认。代价是四步里任何一步出错都会传到最后——分类错了，摘要和周报跟着错。所以第 4 步的“人工确认”不是可选项，而是整条流程的兜底。</p><p>这个推演只说明两种组织的差别和失败的传导方式，不代表真实部署就是这四步——真实的流程还要处理重试、日志和权限，这些正是工作流额外的维护成本。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>两者不是优劣关系，而是适用任务不同：</p><table tabindex="0"><thead><tr><th>维度</th><th>模板</th><th>工作流</th></tr></thead><tbody><tr><td>本质</td><td>固定骨架加填空</td><td>多步骤编排，含条件分支与工具调用</td></tr><tr><td>灵活性</td><td>低：结构固定，只换内容</td><td>高：按输入走不同路径</td></tr><tr><td>维护成本</td><td>低：改文字即可</td><td>高：步骤、接口、依赖都要维护</td></tr><tr><td>失败模式</td><td>填错位置、内容与骨架不匹配</td><td>单步错误被放大、死循环、成本失控</td></tr><tr><td>适用任务</td><td>格式固定、人工判断为主、低频</td><td>步骤明确、可自动化、高频重复</td></tr><tr><td>典型例子</td><td>周报骨架、翻译指令模板</td><td>每周邮件整理、ComfyUI 节点图</td></tr></tbody></table><p>选型时先问一句：变的只有内容，还是过程也要变？前者用模板，后者才考虑工作流。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“工作流比模板高级，都应该用工作流”</strong>：任务简单时，工作流只增加维护负担，按任务形态选择。</li><li><strong>“步骤越多越智能”</strong>：每步的错误会连乘，步骤越多整体可靠性越低，能合并的步骤应合并。</li><li><strong>“导入工作流就能跑”</strong>：以 ComfyUI 为例，工作流依赖模型文件、节点和路径，报错信息通常已经指出缺什么，先看报错再动手。</li><li><strong>“工作流能替代模型”</strong>：工作流没有生成能力，它只组织流程；能力上限仍由模型决定。</li><li><strong>“搭好就一劳永逸”</strong>：上游格式、模型版本、接口的变化都会让流程失效，需要定期维护。</li><li><strong>“出错就整条重跑”</strong>：先固定其他步骤、逐段定位，比整条重跑更容易找到根因。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-一个任务现在用模板够用-出现什么信号说明该考虑工作流" tabindex="-1">1. 一个任务现在用模板够用，出现什么信号说明该考虑工作流？ <a class="header-anchor" href="#_1-一个任务现在用模板够用-出现什么信号说明该考虑工作流" aria-label="Permalink to &quot;1. 一个任务现在用模板够用，出现什么信号说明该考虑工作流？&quot;">​</a></h3><details><summary>查看答案</summary><p>出现下列任一信号：步骤之间有了先后依赖；需要按情况走不同分支；需要调用外部工具或数据；执行频率高到人工逐步操作成为负担。满足其一才考虑升级，否则模板加人工更省。</p></details><h3 id="_2-四步工作流每步正确率-95-整体成功率约多少-这说明什么" tabindex="-1">2. 四步工作流每步正确率 95%，整体成功率约多少？这说明什么？ <a class="header-anchor" href="#_2-四步工作流每步正确率-95-整体成功率约多少-这说明什么" aria-label="Permalink to &quot;2. 四步工作流每步正确率 95%，整体成功率约多少？这说明什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>约 81%（0.95 的 4 次方约等于 0.814）。单看每一步都挺可靠，连乘之后整体明显下降；步骤越多下降越快。所以工作流需要在关键节点设检查点、落盘中间结果，并保留人工确认。</p></details><h3 id="_3-comfyui-的节点图和-预设好的默认参数包-分别对应本页哪个概念" tabindex="-1">3. ComfyUI 的节点图和“预设好的默认参数包”分别对应本页哪个概念？ <a class="header-anchor" href="#_3-comfyui-的节点图和-预设好的默认参数包-分别对应本页哪个概念" aria-label="Permalink to &quot;3. ComfyUI 的节点图和“预设好的默认参数包”分别对应本页哪个概念？&quot;">​</a></h3><details><summary>查看答案</summary><p>节点图对应工作流：连线规定了数据流经的步骤和顺序。预设好的模型、参数、负向提示词和保存路径对应模板：它是可复用的起点，不是执行逻辑本身。两者可以组合——一份搭好的工作流可以保存成模板。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>前置概念：</strong> <a href="/prompting/basics">Prompt 入门</a>说明单步任务怎样表达清楚。</li><li><strong>同主题：</strong> <a href="/llm/rag-agent">RAG 与 Agent</a>用于比较固定流程与模型动态决策。</li><li><strong>工具选择：</strong> <a href="/tools/common-tools">常用工具</a>展示这些流程可以落在哪些工具形态上。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://github.com/Comfy-Org/ComfyUI" target="_blank" rel="noreferrer">ComfyUI 官方仓库</a>：节点式工作流的代表实现，含文档入口与发布说明。</li><li><a href="https://docs.comfy.org" target="_blank" rel="noreferrer">ComfyUI 官方文档</a>：工作流、节点与模型加载的官方说明（含中文版）。</li><li><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Anthropic：Building Effective Agents</a>：区分固定工作流与动态 Agent 的工程建议。</li><li><a href="https://developers.openai.com/api/docs/guides/function-calling" target="_blank" rel="noreferrer">OpenAI：Function Calling 指南</a>：工作流中“工具调用”一步的官方接口文档。</li><li><a href="https://docs.langchain.com" target="_blank" rel="noreferrer">LangChain 文档</a>：把模型调用、检索与步骤编排起来的框架文档。</li></ul>`,53)])])}const u=a(n,[["render",s]]);export{g as __pageData,u as default};
